#!/usr/bin/env Rscript
# ============================================================================
# plot.R — trua1a rRNA tissue-specific modification-level boxplot
#
# Input (generated by data_prep.sh):
#   tissue_specificity_ratio_summary.tsv
#     panel_id | genotype | tissue | site_id | ratio | n_replicates
#
# Output:
#   trua1a_tissue_specificity_boxplot.pdf / .png / .svg
#   tissue_specificity_statistics.tsv
# ============================================================================

suppressPackageStartupMessages({
  library(dplyr)
  library(ggplot2)
  library(scales)
  library(tidyr)
})

script_arg <- grep("^--file=", commandArgs(trailingOnly = FALSE), value = TRUE)
script_dir <- if (length(script_arg) > 0) {
  dirname(normalizePath(sub("^--file=", "", script_arg[1])))
} else {
  normalizePath(getwd())
}
shared_dir <- file.path(script_dir, "..", "..", "..", "shared")
if (!file.exists(file.path(shared_dir, "plot_style.R"))) {
  stop("shared plot_style.R not found: ", normalizePath(file.path(shared_dir, "plot_style.R")))
}
source(file.path(shared_dir, "plot_style.R"))
source(file.path(shared_dir, "plot_tokens.R"))

input_file <- file.path(script_dir, "tissue_specificity_ratio_summary.tsv")
if (!file.exists(input_file)) {
  stop("Input table not found: ", input_file, "\nRun data_prep.sh first.")
}

plot_df <- read.table(
  input_file,
  header = TRUE,
  sep = "\t",
  quote = "",
  comment.char = "",
  stringsAsFactors = FALSE,
  check.names = FALSE
) |>
  mutate(
    genotype = factor(genotype, levels = c("WT", "mutant")),
    tissue = factor(tissue, levels = c("Root", "Leaf", "Flower")),
    group = factor(
      paste(genotype, tissue, sep = "_"),
      levels = c(
        "WT_Root", "WT_Leaf", "WT_Flower",
        "mutant_Root", "mutant_Leaf", "mutant_Flower"
      )
    ),
    ratio = as.numeric(ratio)
  )

required_groups <- paste(
  rep(c("WT", "mutant"), each = 3),
  rep(c("Root", "Leaf", "Flower"), times = 2),
  sep = "_"
)
observed_groups <- as.character(unique(plot_df$group))
missing_groups <- setdiff(required_groups, observed_groups)
if (length(missing_groups) > 0) {
  stop("Missing plotting groups: ", paste(missing_groups, collapse = ", "))
}
if (anyNA(plot_df$ratio) || any(!is.finite(plot_df$ratio))) {
  stop("Ratio summary contains NA or non-finite values.")
}

# Reproduce the reference design: paired tests use the same union site in both
# compared tissues. Asterisks follow the conventional thresholds.
format_p_label <- function(p_value) {
  if (is.na(p_value)) return("ns")
  if (p_value < 0.001) return("***")
  if (p_value < 0.01) return("**")
  if (p_value < 0.05) return("*")
  "ns"
}

comparisons <- list(
  list(group1 = "WT_Flower", group2 = "WT_Root"),
  list(group1 = "WT_Flower", group2 = "WT_Leaf"),
  list(group1 = "mutant_Flower", group2 = "mutant_Root"),
  list(group1 = "mutant_Flower", group2 = "mutant_Leaf")
)

max_ratio <- max(plot_df$ratio, na.rm = TRUE)
annotation_step <- 0.06
sig_rows <- lapply(seq_along(comparisons), function(i) {
  comp <- comparisons[[i]]
  paired_df <- plot_df |>
    filter(group %in% c(comp$group1, comp$group2)) |>
    select(group, site_id, ratio) |>
    pivot_wider(names_from = group, values_from = ratio) |>
    filter(!is.na(.data[[comp$group1]]), !is.na(.data[[comp$group2]]))

  if (nrow(paired_df) < 2) {
    stop("At least two paired sites are required for ", comp$group1, " vs ", comp$group2)
  }

  test_result <- tryCatch(
    t.test(paired_df[[comp$group1]], paired_df[[comp$group2]], paired = TRUE),
    error = function(e) NULL
  )
  p_value <- if (is.null(test_result)) NA_real_ else test_result$p.value
  mean_difference <- mean(paired_df[[comp$group1]] - paired_df[[comp$group2]])

  data.frame(
    comparison = paste(comp$group1, "vs", comp$group2),
    n_sites = nrow(paired_df),
    mean_difference = mean_difference,
    p_value = p_value,
    label = format_p_label(p_value),
    x1 = match(comp$group1, required_groups),
    x2 = match(comp$group2, required_groups),
    y = max_ratio + annotation_step * i,
    stringsAsFactors = FALSE
  )
})
sig_table <- bind_rows(sig_rows)

write.table(
  sig_table |>
    transmute(comparison, n_sites, mean_difference, p_value, label),
  file.path(script_dir, "tissue_specificity_statistics.tsv"),
  sep = "\t",
  quote = FALSE,
  row.names = FALSE,
  na = "NA"
)

# Grey for WT and pink for trua1a, matching the archived TRUA1A reference.
genotype_colors <- c("WT" = "#8A8A8ACC", "mutant" = "#F08E9BCC")

init_theme(base_size = SIZE_TOKENS$base_size, border = TRUE)

p <- ggplot(plot_df, aes(x = group, y = ratio, fill = genotype)) +
  geom_boxplot(
    width = 0.68,
    outlier.shape = NA,
    color = "black",
    linewidth = SIZE_TOKENS$base_linewidth
  ) +
  geom_point(
    position = position_jitter(width = 0.12, height = 0, seed = 1),
    shape = 21,
    size = 2.0,
    stroke = SIZE_TOKENS$base_linewidth / 2,
    color = "black",
    alpha = 0.9
  ) +
  scale_fill_manual(values = genotype_colors, drop = FALSE) +
  scale_x_discrete(
    # 内部 group 键保持单数, 仅显示层改复数
    labels = c("Roots", "Leaves", "Flowers", "Roots", "Leaves", "Flowers")
  ) +
  scale_y_continuous(
    breaks = seq(0, 1, by = 0.2),
    labels = percent_format(accuracy = 1),
    expand = expansion(mult = c(0, 0.02))
  ) +
  labs(
    x = NULL,
    y = expression(paste(psi, " modification level (%)")),
    fill = NULL
  ) +
  coord_cartesian(ylim = c(0, max_ratio + 0.30), clip = "off") +
  theme(
    axis.text.x = element_text(
      size = SIZE_TOKENS$axis_text_size,
      angle = 45, hjust = 1, vjust = 1
    ),
    axis.text.y = element_text(size = SIZE_TOKENS$axis_text_size),
    legend.position = "right",
    legend.text = element_text(size = SIZE_TOKENS$legend_text_size),
    legend.key.height = unit(14, "points"),
    plot.margin = margin(12, 18, 10, 12)
  )

# Add paired-test brackets manually so PDF/SVG remain editable vector objects.
p <- p +
  geom_segment(
    data = sig_table,
    aes(x = x1, xend = x2, y = y, yend = y),
    inherit.aes = FALSE,
    linewidth = SIZE_TOKENS$base_linewidth,
    lineend = "butt"
  ) +
  geom_segment(
    data = sig_table,
    aes(x = x1, xend = x1, y = y, yend = y - 0.015),
    inherit.aes = FALSE,
    linewidth = SIZE_TOKENS$base_linewidth,
    lineend = "butt"
  ) +
  geom_segment(
    data = sig_table,
    aes(x = x2, xend = x2, y = y, yend = y - 0.015),
    inherit.aes = FALSE,
    linewidth = SIZE_TOKENS$base_linewidth,
    lineend = "butt"
  ) +
  geom_text(
    data = sig_table,
    aes(x = (x1 + x2) / 2, y = y + 0.015, label = label),
    inherit.aes = FALSE,
    family = "Arial",
    fontface = "bold",
    size = 6.2,
    color = "black"
  )

save_plot(
  p,
  file.path(script_dir, "trua1a_tissue_specificity_boxplot"),
  width = 8,
  height = 6.04,
  dpi = 600
)

message("[plot] Done: trua1a_tissue_specificity_boxplot.pdf/.png/.svg")
message("[plot] Wrote paired-test table: tissue_specificity_statistics.tsv")
